import { useCallback, useEffect, useState } from 'react';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useSetOnBack } from '~/widgets/sub-layout/use-sub-layout';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { ArsRequest } from '~/entities/pin/api/dtos/types';
import { useArsNumber1Mutation, useArsNumber2Mutation } from '~/entities/pin/api/use-ars-number-mutation';
import { useGetCstmrInfoMutation } from '~/entities/user/api/use-get-cstmr-info-mutation';
import { setUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { useUpdateCstmrAccountMutation } from '~/entities/user/api/use-update-cstmr-account-mutation';
import { SuperAppCommandInbound, VerificationType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { notiBar } from '~/shared/lib/toast';
import { PATHS } from '~/shared/routes/paths';

export const ArsNumberPage = () => {
  const { routerState: backState } = useGetRouterState<SuperAppEncData>();
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const { navigate } = useNavigate();
  useSetOnBack(() => {
    navigate(PATHS.signUp.termsAndConditions, { replace: true, state: { ...backState } });
  });
  const [arsNumber, setArsNumber] = useState<number>();
  const [isFail, setIsFail] = useState<boolean>(false);
  const { mutateAsync: arsNumber1 } = useArsNumber1Mutation();
  const { mutateAsync: arsNumber2 } = useArsNumber2Mutation();
  const { mutateAsync: updateCstmr } = useUpdateCstmrAccountMutation();
  const { mutateAsync: getCstmrInfo } = useGetCstmrInfoMutation();

  const onSubmit = useCallback(async () => {
    const reqData: SuperAppEncData = { ...state };
    const req: ArsRequest = {
      customerId: reqData.cstmrNo,
      koreanNm: reqData.koreanNm,
      acnutNo: reqData.acnutno,
      telecomTypeCd: reqData.telecomTypeCd,
      mbtlnum: reqData.mbtlnum,
      rlnmNo: reqData.rlnmNo
        ? (['1', '2', '5', '6'].includes((reqData.rlnmNo || '').charAt(6)) ? '19' : '20') +
          (reqData.rlnmNo || '').substring(0, 6)
        : '',
      gender: reqData.rlnmNo
        ? ['1', '3', '5', '7', '9'].includes((reqData.rlnmNo || '').charAt(6))
          ? ' 01'
          : '02'
        : '',
      reqType: '01',
      arsPinNo: arsNumber,
    };
    // TODO: 게이트웨이 ARS2 api
    const response = await arsNumber2(req);
    if (response) {
      if (state?.command === SuperAppCommandInbound.지갑생성_요청) {
        if (reqData?.verificationType === VerificationType.ReSetUser) {
          await updateCstmr({ ci: reqData.ci, acnutno: reqData.acnutno, koreanNm: reqData.koreanNm });
          await getCstmrInfo();
          notiBar(i18n.t('text:linkedAccountChanged'));
          navigate(PATHS.account.myBankAccount, { replace: true });
        } else {
          setUserRes((prev) => ({
            ...prev,
            tbCstmrMastr: {
              ...prev.tbCstmrMastr,
              ...reqData,
            },
          }));
          navigate(PATHS.pin.set, { replace: true, state: { ...reqData } });
        }
      }

      if (state?.command === SuperAppCommandInbound.지갑추가_요청) {
        setUserRes((prev) => ({
          ...prev,
          tbCstmrMastr: {
            ...prev.tbCstmrMastr,
            ...reqData,
          },
        }));
        navigate(PATHS.pin.login, { replace: true, state: { ...reqData } });
      }
    } else {
      setIsFail(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [arsNumber]);
  const handleReTry = async () => {
    setIsFail(false);
    handleNumber();
  };

  const handleNumber = () => {
    // TODO: 게이트웨이 ARS1 api
    arsNumber1({});
    setArsNumber(Math.floor((window.crypto.getRandomValues(new Uint8Array(1))[0] / 256) * 99 + 1));
  };
  useEffect(() => {
    handleNumber();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="has-btm-btn bottom-fixed flex flex-auto flex-col">
      {isFail ? (
        <>
          <div className="sub-desc">
            <p
              className="desc-sub"
              dangerouslySetInnerHTML={{
                __html: i18n.t('text:arsRequestRetry'),
              }}
            />
          </div>
          <div className="ars-num-area">
            <div className="ars-num-chk"></div>
            <div className="ars-desc">
              <ul>
                <li>{i18n.t('text:contactCustomerServiceForOtherAuth')}</li>
              </ul>
            </div>
          </div>
        </>
      ) : (
        <>
          <div className="sub-desc">
            <p className="desc-sub">
              {i18n.t('text:arsCallingInProgress')}
              <br />
              <span
                dangerouslySetInnerHTML={{
                  __html: i18n.t('text:arsApprovalNumberInstruction'),
                }}
              />
            </p>
          </div>

          <div className="ars-num-area">
            <div className="ars-num-chk">
              <p>{i18n.t('approvalNumber')}</p>
              <p className="ars-num">{arsNumber}</p>
            </div>
            <div className="ars-desc">
              <ul>
                <li
                  dangerouslySetInnerHTML={{
                    __html: i18n.t('text:pressConfirmAfterApproval'),
                  }}
                />
                <li>{i18n.t('text:checkPhoneNumberIfNoCall')}</li>
                <li>{i18n.t('text:callForwardingNotAllowed')}</li>
              </ul>
            </div>
          </div>
        </>
      )}
      <div className="btm-btn-area confirm half">
        <button
          type="button"
          className={'btm-btn'}
          onClick={() => navigate(PATHS.signUp.termsAndConditions, { replace: true, state: { ...backState } })}
        >
          {i18n.t('goToPreviousPage')}
        </button>
        {isFail ? (
          <button type="button" className={'btm-btn app'} onClick={handleReTry}>
            {i18n.t('resend')}
          </button>
        ) : (
          <button type="button" className={'btm-btn app'} onClick={onSubmit}>
            {i18n.t('confirm')}
          </button>
        )}
      </div>
    </div>
  );
};
