import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { UserResponse } from '~/entities/pin/api/dtos/schemas';
import { transformUserWithTokenList } from '~/entities/user/lib/transform-user-with-token-list';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';
import { setUserRes } from './use-get-cstmr-query';

const getCstmrInfo = () => {
  return resultify(axios.get<UserResponse>(API_URLS.cstmr('detail')));
};

export const useGetCstmrInfoMutation = (options?: MutationOptions<void, CBDCAxiosError, UserResponse>) => {
  const mutation = useMutation<UserResponse, CBDCAxiosError, void>({
    ...options,
    mutationFn: () => getCstmrInfo(),
    onSuccess: (data) => {
      const serverUserInfo = data?.tbCstmrMastr;
      if (serverUserInfo) {
        const userInfo = transformUserWithTokenList(serverUserInfo);
        setUserRes((prev) => ({
          ...prev,
          tbCstmrMastr: {
            ...prev.tbCstmrMastr,
            ...userInfo,
          },
        }));
      }
    },
  });

  return {
    ...mutation,
  };
};
